    authorityPda: TAccountMetas[2];
    /** Seller of the tokens */
    seller: TAccountMetas[3];
    mint: TAccountMetas[4];
    tokenAccount: TAccountMetas[5];
    authorityPdaTokenAccount: TAccountMetas[6];
    tokenProgram: TAccountMetas[7];
